"""Package actual browser screenshots into an offline, self-contained visual preview."""
from pathlib import Path
import base64
import html
root=Path('/workspace/artifacts')
views=[('dashboard','خانه و نمای کلی','rasta-dashboard.png'),('project','هدف و مراحل پروژه','rasta-project.png'),('task','مودال تسک','rasta-task.png'),('mobile','نمای موبایل','rasta-mobile.png')]
font=next(Path('public/build/assets').glob('vazirmatn-arabic-400-normal-*.woff2'))
font_data=base64.b64encode(font.read_bytes()).decode()
tabs=''.join(f'<button role="tab" id="tab-{k}" aria-controls="view-{k}" aria-selected="{str(i==0).lower()}" onclick="showView(\'{k}\')">{label}</button>' for i,(k,label,_) in enumerate(views))
images=''.join(f'<section id="view-{k}" role="tabpanel" aria-labelledby="tab-{k}" {"hidden" if i else ""}><img class="{k}" alt="{html.escape(label)} — تصویر واقعی برنامه راستا" src="data:image/png;base64,{base64.b64encode((root/file).read_bytes()).decode()}"></section>' for i,(k,label,file) in enumerate(views))
page='''<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>پیش‌نمایش راستا</title><style>
@font-face{font-family:Vazir;src:url(data:font/woff2;base64,FONTDATA) format('woff2')}*{box-sizing:border-box}body{margin:0;background:#f5f3ee;color:#30352e;font:14px/1.9 Vazir,sans-serif}header{padding:24px 30px;background:#fff;border-bottom:1px solid #e6e5dd}header>div{max-width:1400px;margin:auto;display:flex;align-items:center;justify-content:space-between;gap:15px}h1{margin:0;font-size:24px;color:#bb623b}p{font-size:12px;margin:4px 0;color:#859074}small{color:#9bA48e;font-size:11px}nav{position:sticky;top:0;padding:15px 20px;display:flex;justify-content:center;gap:8px;background:#f5f3eef5;backdrop-filter:blur(10px);z-index:2}button{font:12px Vazir,sans-serif;border:1px solid #dedfd5;border-radius:8px;padding:9px 16px;background:#fff;color:#6e7b5f;cursor:pointer}button[aria-selected=true]{background:#d76a3c;color:white;border-color:#d76a3c}button:focus-visible{outline:3px solid #b67e55;outline-offset:2px}main{max-width:1460px;margin:auto;padding:0 24px 40px}section{border:1px solid #e3e4db;border-radius:14px;overflow:hidden;background:#fff;box-shadow:0 12px 50px #38452b0b}img{width:100%;display:block;height:auto}section:has(img.mobile){max-width:390px;margin:auto}footer{text-align:center;padding:0 20px 30px;font-size:11px;color:#8c997b}[hidden]{display:none}@media(max-width:600px){header{padding:18px}header>div{display:block}h1{font-size:21px}nav{padding:12px 8px;gap:5px}button{font-size:10px;padding:8px}main{padding:0 9px 25px}section{border-radius:8px}}
</style><header><div><div><h1>راستا <span style="color:#626e55;font-size:16px"> / پیش‌نمایش رابط</span></h1><p>هر قدم، نزدیک‌تر به هدف.</p></div><small>تصاویر واقعی از برنامه اجراشده · فارسی و راست‌به‌چپ</small></div></header><nav role="tablist" aria-label="انتخاب صفحه">TABS</nav><main>IMAGES</main><footer>این فایل پیش‌نمایش تصویری است؛ برای کار با فرم‌ها و ذخیره اطلاعات، نسخه Laravel پروژه را اجرا کنید.</footer><script>function showView(key){document.querySelectorAll('[role=tabpanel]').forEach(el=>el.hidden=el.id!=='view-'+key);document.querySelectorAll('[role=tab]').forEach(el=>el.setAttribute('aria-selected',String(el.id==='tab-'+key)));window.scrollTo({top:0,behavior:'smooth'});}document.querySelector('nav').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const tabs=[...document.querySelectorAll('[role=tab]')];let i=tabs.indexOf(document.activeElement);i=(i+(e.key==='ArrowLeft'?1:-1)+tabs.length)%tabs.length;tabs[i].focus();tabs[i].click();});</script></html>'''
(root/'rasta-preview.html').write_text(page.replace('FONTDATA',font_data).replace('TABS',tabs).replace('IMAGES',images))
print('Saved /workspace/artifacts/rasta-preview.html')
